    private static void generateSubsets(int index, long sum) {
        if (index == allNumbers.size()) {
            subsetValues.add(sum);
            return;
        }
        generateSubsets(index + 1, sum + allNumbers.get(index));
        generateSubsets(index + 1, sum);
