#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
using namespace std;

vector<long long> subsetValues, allNumbers;

void generateSubsets(int index, long long sum) {
    if (index == (int)allNumbers.size()) {
        subsetValues.push_back(sum);
        return;
    }
    generateSubsets(index + 1, sum + allNumbers[index]);
    generateSubsets(index + 1, sum);
}

bool checkSum(long long M, long long W, long long x) {
    if (x == M) return true;

    long long total = x + M;
    while (total > 0) {
        if (total % W > 1) return false;
        total /= W;
    }
    return true;
}

int main() {
    string line;
    getline(cin, line);
    stringstream ss(line);
    long long W, M;
    ss >> W >> M;

    if (W == 2) {
        cout << "YES" << endl;
        return 0;
    }

    allNumbers.clear();
    allNumbers.push_back(1LL);
    allNumbers.push_back(W);

    long long val = W;
    const long long MAX_VAL = 10000000000LL; // 1e10

    while (true) {
        val *= W;
        if (val < 0 || val > MAX_VAL) break;
        allNumbers.push_back(val);
    }

    subsetValues.clear();
    generateSubsets(0, 0);

    bool resultFlag = false;
    for (long long candidate : subsetValues) {
        resultFlag |= checkSum(M, W, candidate);
        if (resultFlag) break;
    }

    cout << (resultFlag ? "YES" : "NO") << endl;
    return 0;
}
